def __init__(
    self,
    headers: HeaderTypes | None = None,
    encoding: str | None = None,
) -> None:
    self._list = []  # type: typing.List[typing.Tuple[bytes, bytes, bytes]]

    if isinstance(headers, Headers):
        self._list = list(headers._list)
    elif isinstance(headers, Mapping):
        for k, v in headers.items():
            bytes_key = _normalize_header_key(k, encoding)
            bytes_value = _normalize_header_value(v, encoding)
            self._list.append((bytes_key, bytes_key.lower(), bytes_value))
    elif headers is not None:
        for k, v in headers:
            bytes_key = _normalize_header_key(k, encoding)
            bytes_value = _normalize_header_value(v, encoding)
            self._list.append((bytes_key, bytes_key.lower(), bytes_value))

    self._encoding = encoding

def _prepare(self, default_headers: dict[str, str]) -> None:
    for key, value in default_headers.items():
        # Ignore Transfer-Encoding if the Content-Length has been set explicitly.
        if key.lower() == "transfer-encoding" and "Content-Length" in self.headers:
            continue
        self.headers.setdefault(key, value)

    auto_headers: list[tuple[bytes, bytes]] = []

    has_host = "Host" in self.headers
    has_content_length = (
        "Content-Length" in self.headers or "Transfer-Encoding" in self.headers
    )

    if not has_host and self.url.host:
        auto_headers.append((b"Host", self.url.netloc))
    if not has_content_length and self.method in ("POST", "PUT", "PATCH"):
        auto_headers.append((b"Content-Length", b"0"))

    self.headers = Headers(auto_headers + self.headers.raw)

def get(self, key: str, default: typing.Any = None) -> typing.Any:
    """
    Return a header value. If multiple occurrences of the header occur
    then concatenate them together with commas.
    """
    try:
        return self[key]
    except KeyError:
        return default

def __contains__(self, key: typing.Any) -> bool:
    header_key = key.lower().encode(self.encoding)
    return header_key in [key for _, key, _ in self._list]

@property
def raw(self) -> list[tuple[bytes, bytes]]:
    """
    Returns a list of the raw header items, as byte pairs.
    """
    return [(raw_key, value) for raw_key, _, value in self._list]

def __iter__(self) -> typing.Iterator[bytes]:
    for chunk in self.iter_chunks():
        yield chunk

def iter_chunks(self) -> typing.Iterator[bytes]:
    for field in self.fields:
        yield b"--%s\r\n" % self.boundary
        yield from field.render()
        yield b"\r\n"
    yield b"--%s--\r\n" % self.boundary

def __init__(
    self,
    data: RequestData,
    files: RequestFiles,
    boundary: bytes | None = None,
) -> None:
    if boundary is None:
        boundary = os.urandom(16).hex().encode("ascii")

    self.boundary = boundary
    self.content_type = "multipart/form-data; boundary=%s" % boundary.decode(
        "ascii"
    )
    self.fields = list(self._iter_fields(data, files))

def _iter_fields(
    self, data: RequestData, files: RequestFiles
) -> typing.Iterator[FileField | DataField]:
    for name, value in data.items():
        if isinstance(value, (tuple, list)):
            yield DataField(name=name, value=str(value))
        else:
            yield DataField(name=name, value=value)

    file_items = files.items() if isinstance(files, typing.Mapping) else files
    for name, value in file_items:
        yield FileField(name=name, value=value)

def __init__(self, name: str, value: str | bytes | int | float | None) -> None:
    if not isinstance(name, str):
        raise TypeError(
            f"Invalid type for name. Expected str, got {type(name)}: {name!r}"
        )
    if value is not None and not isinstance(value, (str, bytes, int, float)):
        raise TypeError(
            "Invalid type for value. Expected primitive type,"
            f" got {type(value)}: {value!r}"
        )
    self.name = name
    self.value: str | bytes = (
        value if isinstance(value, bytes) else primitive_value_to_str(value)
    )

@pytest.mark.parametrize('leading', [0,1,3])
def test_observed_records(leading):
    events=[]
    def app(environ,start_response):
        def body():
            try:
                for _ in range(leading): yield b''
                start_response('202 Accepted',[('Content-Type','text/plain'),('X-Mode','lazy')])
                events.append(environ['PATH_INFO'])
                yield b'first'; yield b''; yield b'last'
            finally: events.append('closed')
        return body()
    with httpx.Client(transport=httpx.WSGITransport(app),base_url='http://case.invalid',trust_env=False) as client:
        response=client.get('[EXTERNAL]/lazy')
    assert response.status_code==202 and response.headers['x-mode']=='lazy'
    assert response.content==b'firstlast' and events==['[EXTERNAL]/lazy','closed']

def __enter__(self: T) -> T:
    if self._state != ClientState.UNOPENED:
        msg = {
            ClientState.OPENED: "Cannot open a client instance more than once.",
            ClientState.CLOSED: (
                "Cannot reopen a client instance, once it has been closed."
            ),
        }[self._state]
        raise RuntimeError(msg)

    self._state = ClientState.OPENED

    self._transport.__enter__()
    for transport in self._mounts.values():
        if transport is not None:
            transport.__enter__()
    return self

def __init__(self, result: typing.Iterable[bytes]) -> None:
    self._close = getattr(result, "close", None)
    self._result = iter(result)

@property
def path(self) -> str:
    """
    The URL path as a string. Excluding the query string, and URL decoded.

    For example:

    url = httpx.URL("https://example.com/pa%20th")
    assert url.path == "[EXTERNAL]/pa th"
    """
    path = self._uri_reference.path or "[EXTERNAL]/"
    return unquote(path)

